#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
using namespace std;

const int INF = 1034567890;
const int MAX_NODE = 100000;
const int MAX_EDGE = 1000000;

struct Edge {
    int to, capacity, cost, type;
    Edge(int t=0, int c=0, int v=0, int ty=0): to(t), capacity(c), cost(v), type(ty) {}
};

vector<int> adj[MAX_NODE];
Edge edges[MAX_EDGE];
int edgeCount;
int sink;
int C, d;

void clearFlow(int sinkNode) {
    sink = sinkNode;
    for (int i=0; i<=sink; ++i) adj[i].clear();
    edgeCount=0;
}

void addEdge(int from, int to, int capacity, int cost, int type) {
    adj[from].push_back(edgeCount);
    edges[edgeCount]=Edge(to, capacity, cost, type);
    edgeCount++;
    adj[to].push_back(edgeCount);
    if (type==1) {
        edges[edgeCount]=Edge(from,0,-C+d,type);
        edgeCount++;
    } else {
        edges[edgeCount]=Edge(from,0,-cost,type);
        edgeCount++;
    }
}

int minCost[MAX_NODE], dist[MAX_NODE], queue[MAX_NODE*10], inQueue[MAX_NODE];

int flow() {
    for (int i=0; i<=sink; ++i) {
        minCost[i]=INF;
        inQueue[i]=0;
    }
    minCost[sink]=INF;
    int front=0, rear=1;
    queue[0]=0;
    minCost[0]=0;
    while (front<rear) {
        int u=queue[front++];
        inQueue[u]=0;
        for (int r:adj[u]) {
            int v=edges[r].to;
            if (edges[r].capacity>0 && minCost[u]+edges[r].cost<minCost[v]) {
                minCost[v]=minCost[u]+edges[r].cost;
                if (!inQueue[v]) {
                    inQueue[v]=1;
                    queue[rear++]=v;
                }
            }
        }
    }
    if (minCost[sink]==INF) return -1;
    int current=sink;
    while (current!=0) {
        int r=0;
        for (int idx:adj[current]) {
            if (edges[idx].to==current && edges[idx^1].capacity>0 && minCost[current]==minCost[edges[idx].to]+edges[idx].cost) {
                r=idx;
                break;
            }
        }
        if (edges[r].type==1) {
            if ((r&1)==1) {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            } else {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            }
        }
        edges[r].capacity--;
        edges[r^1].capacity++;
        current=edges[r^1].to;
    }
    return minCost[sink];
}

int solve(int n) {
    int total=0;
    for (int i=0; i<n; ++i) total+=flow();
    return total;
}

int main() {
    int n,m,k;
    cin>>n>>m>>k>>C>>d;
    clearFlow(n*100+1);
    for (int i=1; i<=k; ++i) {
        int x; cin>>x;
        addEdge(0,x,1,0,0);
    }
    for (int i=1; i<=99; ++i) {
        addEdge(1+i*n,100*n+1,INF,0,0);
    }
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=99; ++j) {
            addEdge(i+(j-1)*n,i+j*n,INF,C,0);
        }
    }
    for (int i=1; i<=m; ++i) {
        int x,y; cin>>x>>y;
        for (int j=1; j<=99; ++j) {
            addEdge(x+(j-1)*n,y+j*n,INF,C+d,1);
            addEdge(y+(j-1)*n,x+j*n,INF,C+d,1);
        }
    }
    cout<<solve(k)<<endl;
    return 0;
}
